/*
 * GD32H759 path: backend wrapping the code generated by GigaDevice GD32 Embedded AI.
 *
 * The tool generates a Keil or IAR project containing the model and its inference code.
 * Its public API names are not documented publicly, so the two calls below are
 * placeholders. After the first tool run, replace them with the generated functions
 * (VERIFY) and keep this wrapper's contract:
 *   - input: float, normalised window [60][9], oldest first (exactly what the tool was given
 *     in calib.npz / test.npz), unless the generated API wants int8: then quantise here with
 *     the tool's reported input scale and zero point
 *   - output: 4 class probabilities
 */
#include "ai_backend.h"
#include "generated/ai_scaler.h"

/* ---- replace with the GD32 Embedded AI generated API (VERIFY) ---- */
extern int gd32ai_model_init(void);
extern int gd32ai_model_run(const float *input, float *output);
/* ------------------------------------------------------------------ */

static pal_status_t gd32_init(void)
{
    return gd32ai_model_init() == 0 ? PAL_OK : PAL_ERR;
}

static pal_status_t gd32_infer(const float *x, float *probs)
{
    return gd32ai_model_run(x, probs) == 0 ? PAL_OK : PAL_ERR;
}

static const ai_backend_t k_backend = { "gd32-embedded-ai (GD32H759)", gd32_init, gd32_infer };

const ai_backend_t *ai_backend_get(void) { return &k_backend; }
